cat > /tmp/final_check.mjs <<'EOF'
import { parseSource } from '/app/src/parser.ts';

let failures = 0;
function expectError(code, options, substring, label) {
  try {
    parseSource(code, options);
    console.log('FAIL (expected error):', label);
    failures++;
  } catch (e) {
    if (!e.message.includes(substring)) {
      console.log('FAIL (wrong msg):', label, '=>', e.message.split(']: ')[1], '(expected substring:', substring + ')');
      failures++;
    } else {
      console.log('OK:', label);
    }
  }
}
function expectPass(code, options, label, kind) {
  try {
    const ast = parseSource(code, options);
    if (kind) {
      const found = JSON.stringify(ast).includes(`"kind":"${kind}"`);
      if (!found) {
        console.log('FAIL (wrong kind):', label, '=>', JSON.stringify(ast.body[0]));
        failures++;
      } else {
        console.log('OK:', label);
      }
    } else {
      console.log('OK:', label);
    }
  } catch (e) {
    console.log('FAIL (expected pass):', label, '=>', e.message.split(']: ')[1]);
    failures++;
  }
}

// Error messages
expectError('using foo = null', { next: true }, 'not allowed in the global scope', 'script global scope');
expectError('await using foo = null', { next: true }, 'only allowed inside async', 'await using script top priority');
expectError('function f() { await using foo = null; }', { next: true }, 'only allowed inside async', 'await using non-async fn');
expectError('function f() { using foo; }', { next: true }, 'must have an initializer', 'missing initializer');
expectError('function f() { for (using x in y) {} }', { next: true }, 'not allowed in for-in', 'for-in');
expectError('function f() { using [a] = b; }', { next: true }, 'cannot have destructuring', 'destructuring array');
expectError('function f() { using {a} = b; }', { next: true }, 'cannot have destructuring', 'destructuring object');

// Pass cases
expectPass('using foo = null', { next: true, sourceType: 'module' }, 'using module', 'using');
expectPass('async function f() { await using foo = null; }', { next: true }, 'await using async', 'await using');
expectPass('await using foo = null', { next: true, sourceType: 'module' }, 'await using module', 'await using');
expectPass('for (using x of y) {}', { next: true }, 'for using script top', 'using');
expectPass('for (await using x of y) {}', { next: true, sourceType: 'module' }, 'for await-using module', 'await using');
expectPass('async function f() { for await (using x of y) {} }', { next: true }, 'for await using async', 'using');
expectPass('async function f() { for await (await using x of y) {} }', { next: true }, 'for await await-using async', 'await using');
expectPass('function f() { using\nfoo = 1; }', { next: true }, 'using newline as identifier');

console.log('\nFailures:', failures);
process.exit(failures ? 1 : 0);
EOF
cd /app && ./node_modules/.bin/vite-node /tmp/final_check.mjs 2>&1 | head -40
